  officialScoreLine: ["正式 单次 {p0} · 平均 {p1} 「{p2}」","Adopted: single {p0} · average {p1} [{p2}]","採用：単発 {p0}・平均 {p1}［{p2}］","正式：單次 {p0} · 平均 {p1}「{p2}」","채택: 단일 {p0} · 평균 {p1} [{p2}]","Retenu : meilleur temps {p0} · moyenne {p1} [{p2}]","Adoptado: mejor tiempo {p0} · media {p1} [{p2}]"],
