type Key = `teamMatch.${keyof typeof messages}`;
function catalog(index: 0 | 1 | 2 | 3 | 4 | 5 | 6): Record<Key, string> {
  return Object.fromEntries(Object.entries(messages).map(([key, values]) => [`teamMatch.${key}`, values[index]])) as Record<Key, string>;
}
